-- Table: budget_revision_detail
-- Source: accounting_admin_db.sql (2. Accounting core and budget)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS budget_revision_detail (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    budget_revision_id  BIGINT NOT NULL REFERENCES budget_revision(id) ON DELETE CASCADE,
    line_number         INTEGER NOT NULL CHECK (line_number > 0),
    budget_allocation_detail_id BIGINT REFERENCES budget_allocation_detail(id),
    current_amount      NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (current_amount >= 0),
    requested_amount    NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (requested_amount >= 0),
    difference          NUMERIC(18,2) NOT NULL DEFAULT 0,
    reason              TEXT,
    UNIQUE (budget_revision_id, line_number)
);
